let CreateRefundVendorCredit = class CreateRefundVendorCredit {
    constructor(uow, eventPublisher, branchDTOTransform, refundVendorCreditModel, accountModel, vendorCreditModel) {
        this.uow = uow;
        this.eventPublisher = eventPublisher;
        this.branchDTOTransform = branchDTOTransform;
        this.refundVendorCreditModel = refundVendorCreditModel;
        this.accountModel = accountModel;
        this.vendorCreditModel = vendorCreditModel;
        this.createRefund = async (vendorCreditId, refundVendorCreditDTO) => {
            const vendorCredit = await this.vendorCreditModel()
                .query()
                .findById(vendorCreditId)
                .throwIfNotFound();
            const depositAccount = await this.accountModel()
                .query()
                .findById(refundVendorCreditDTO.depositAccountId)
                .throwIfNotFound();
            this.validateVendorCreditRemainingCredit(vendorCredit, refundVendorCreditDTO.amount);
            this.validateRefundDepositAccountType(depositAccount);
            await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onRefundCreate, {
                vendorCreditId,
                refundVendorCreditDTO,
            });
            const refundCreditObj = await this.transformDTOToModel(vendorCredit, refundVendorCreditDTO);
            return this.uow.withTransaction(async (trx) => {
                const eventPayload = {
                    vendorCredit,
                    trx,
                    refundVendorCreditDTO,
                };
                await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onRefundCreating, eventPayload);
                const refundVendorCredit = await this.refundVendorCreditModel()
                    .query()
                    .insertAndFetch(refundCreditObj);
                await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onRefundCreated, {
                    ...eventPayload,
                    refundVendorCredit,
                });
                return refundVendorCredit;
            });
        };
        this.transformDTOToModel = async (vendorCredit, vendorCreditDTO) => {
            const initialDTO = {
                vendorCreditId: vendorCredit.id,
                ...vendorCreditDTO,
                currencyCode: vendorCredit.currencyCode,
                exchangeRate: vendorCreditDTO.exchangeRate || 1,
            };
            return this.branchDTOTransform.transformDTO(initialDTO);
        };
    }
    validateRefundDepositAccountType(account) {
        const supportedTypes = ['bank', 'cash', 'fixed-asset'];
        if (supportedTypes.indexOf(account.accountType) === -1) {
            throw new ServiceError_1.ServiceError(constants_1.ERRORS.DEPOSIT_ACCOUNT_INVALID_TYPE);
        }
    }
    validateVendorCreditRemainingCredit(vendorCredit, amount) {
        if (vendorCredit.creditsRemaining < amount) {
            throw new ServiceError_1.ServiceError(constants_1.ERRORS.VENDOR_CREDIT_HAS_NO_CREDITS_REMAINING);
        }
    }
};

