let DeleteRefundVendorCreditService = class DeleteRefundVendorCreditService {
    constructor(uow, eventPublisher, refundVendorCreditModel) {
        this.uow = uow;
        this.eventPublisher = eventPublisher;
        this.refundVendorCreditModel = refundVendorCreditModel;
    }
    async deleteRefundVendorCreditRefund(refundCreditId) {
        const oldRefundCredit = await this.refundVendorCreditModel()
            .query()
            .findById(refundCreditId)
            .throwIfNotFound();
        await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onRefundDelete, {
            refundCreditId,
            oldRefundCredit,
        });
        return this.uow.withTransaction(async (trx) => {
            const eventPayload = {
                trx,
                refundCreditId,
                oldRefundCredit,
            };
            await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onRefundDeleting, eventPayload);
            await this.refundVendorCreditModel()
                .query(trx)
                .findById(refundCreditId)
                .delete();
            await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onRefundDeleted, eventPayload);
        });
    }
};

