let EditVendorCreditService = class EditVendorCreditService {
    constructor(eventPublisher, uow, itemsEntriesService, vendorCreditDTOTransform, vendorCreditModel, contactModel) {
        this.eventPublisher = eventPublisher;
        this.uow = uow;
        this.itemsEntriesService = itemsEntriesService;
        this.vendorCreditDTOTransform = vendorCreditDTOTransform;
        this.vendorCreditModel = vendorCreditModel;
        this.contactModel = contactModel;
        this.editVendorCredit = async (vendorCreditId, vendorCreditDTO, trx) => {
            const oldVendorCredit = await this.vendorCreditModel()
                .query()
                .findById(vendorCreditId)
                .throwIfNotFound();
            const vendor = await this.contactModel()
                .query()
                .modify('vendor')
                .findById(vendorCreditDTO.vendorId)
                .throwIfNotFound();
            await this.itemsEntriesService.validateItemsIdsExistance(vendorCreditDTO.entries);
            await this.itemsEntriesService.validateNonSellableEntriesItems(vendorCreditDTO.entries);
            await this.itemsEntriesService.validateEntriesIdsExistance(vendorCreditId, 'VendorCredit', vendorCreditDTO.entries);
            const vendorCreditModel = await this.vendorCreditDTOTransform.transformCreateEditDTOToModel(vendorCreditDTO, vendor.currencyCode, oldVendorCredit);
            return this.uow.withTransaction(async (trx) => {
                await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onEditing, {
                    oldVendorCredit,
                    vendorCreditDTO,
                    trx,
                });
                const vendorCredit = await this.vendorCreditModel()
                    .query(trx)
                    .upsertGraphAndFetch({
                    id: vendorCreditId,
                    ...vendorCreditModel,
                });
                await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onEdited, {
                    oldVendorCredit,
                    vendorCredit,
                    vendorCreditDTO,
                    trx,
                });
                return vendorCredit;
            }, trx);
        };
    }
};

