let EditSaleInvoice = class EditSaleInvoice {
    constructor(itemsEntriesService, eventPublisher, validators, transformerDTO, uow, saleInvoiceModel, customerModel) {
        this.itemsEntriesService = itemsEntriesService;
        this.eventPublisher = eventPublisher;
        this.validators = validators;
        this.transformerDTO = transformerDTO;
        this.uow = uow;
        this.saleInvoiceModel = saleInvoiceModel;
        this.customerModel = customerModel;
        this.tranformEditDTOToModel = async (customer, saleInvoiceDTO, oldSaleInvoice) => {
            return this.transformerDTO.transformDTOToModel(customer, saleInvoiceDTO, oldSaleInvoice);
        };
    }
    async editSaleInvoice(saleInvoiceId, saleInvoiceDTO) {
        const oldSaleInvoice = await this.saleInvoiceModel()
            .query()
            .findById(saleInvoiceId)
            .withGraphJoined('entries');
        this.validators.validateInvoiceExistance(oldSaleInvoice);
        const customer = await this.customerModel()
            .query()
            .findById(saleInvoiceDTO.customerId)
            .throwIfNotFound();
        await this.itemsEntriesService.validateItemsIdsExistance(saleInvoiceDTO.entries);
        await this.itemsEntriesService.validateNonSellableEntriesItems(saleInvoiceDTO.entries);
        await this.itemsEntriesService.validateEntriesIdsExistance(saleInvoiceId, 'SaleInvoice', saleInvoiceDTO.entries);
        const saleInvoiceObj = await this.tranformEditDTOToModel(customer, saleInvoiceDTO, oldSaleInvoice);
        if (saleInvoiceObj.invoiceNo) {
            await this.validators.validateInvoiceNumberUnique(saleInvoiceObj.invoiceNo, saleInvoiceId);
        }
        this.validators.validateInvoiceAmountBiggerPaymentAmount(saleInvoiceObj.balance, oldSaleInvoice.paymentAmount);
        return this.uow.withTransaction(async (trx) => {
            await this.eventPublisher.emitAsync(events_1.events.saleInvoice.onEditing, {
                trx,
                oldSaleInvoice,
                saleInvoiceDTO,
            });
            const saleInvoice = await this.saleInvoiceModel()
                .query()
                .upsertGraphAndFetch({
                id: saleInvoiceId,
                ...saleInvoiceObj,
            });
            const editEventPayload = {
                saleInvoiceId,
                saleInvoice,
                saleInvoiceDTO,
                oldSaleInvoice,
                trx,
            };
            await this.eventPublisher.emitAsync(events_1.events.saleInvoice.onEdited, editEventPayload);
            return saleInvoice;
        });
    }
};

