let EditBillService = class EditBillService {
    constructor(validators, itemsEntriesService, uow, eventPublisher, transactionLandedCostEntries, transformerDTO, billModel, vendorModel) {
        this.validators = validators;
        this.itemsEntriesService = itemsEntriesService;
        this.uow = uow;
        this.eventPublisher = eventPublisher;
        this.transactionLandedCostEntries = transactionLandedCostEntries;
        this.transformerDTO = transformerDTO;
        this.billModel = billModel;
        this.vendorModel = vendorModel;
    }
    async editBill(billId, billDTO) {
        const oldBill = await this.billModel()
            .query()
            .findById(billId)
            .withGraphFetched('entries');
        this.validators.validateBillExistance(oldBill);
        const vendor = await this.vendorModel()
            .query()
            .findById(billDTO.vendorId)
            .throwIfNotFound();
        if (billDTO.billNumber) {
            await this.validators.validateBillNumberExists(billDTO.billNumber, billId);
        }
        await this.itemsEntriesService.validateEntriesIdsExistance(billId, 'Bill', billDTO.entries);
        await this.itemsEntriesService.validateItemsIdsExistance(billDTO.entries);
        await this.itemsEntriesService.validateNonPurchasableEntriesItems(billDTO.entries);
        const billObj = await this.transformerDTO.billDTOToModel(billDTO, vendor, oldBill);
        this.validators.validateBillAmountBiggerPaidAmount(billObj.amount, oldBill.paymentAmount);
        await this.transactionLandedCostEntries.validateLandedCostEntriesNotDeleted(oldBill.entries, billObj.entries);
        await this.transactionLandedCostEntries.validateLocatedCostEntriesSmallerThanNewEntries(oldBill.entries, billObj.entries);
        return this.uow.withTransaction(async (trx) => {
            await this.eventPublisher.emitAsync(events_1.events.bill.onEditing, {
                oldBill,
                billDTO,
                trx,
            });
            const bill = await this.billModel()
                .query(trx)
                .upsertGraphAndFetch({
                id: billId,
                ...billObj,
            });
            await this.eventPublisher.emitAsync(events_1.events.bill.onEdited, {
                oldBill,
                bill,
                billDTO,
                trx,
            });
            return bill;
        });
    }
};

