let ApplyVendorCreditToBillsService = class ApplyVendorCreditToBillsService {
    constructor(uow, eventPublisher, billPaymentValidators, vendorCreditDTOTransform, vendorCreditAppliedBillModel, vendorCreditModel, documentBalance, creditBalance) {
        this.documentBalance = documentBalance;
        this.creditBalance = creditBalance;
        this.uow = uow;
        this.eventPublisher = eventPublisher;
        this.billPaymentValidators = billPaymentValidators;
        this.vendorCreditDTOTransform = vendorCreditDTOTransform;
        this.vendorCreditAppliedBillModel = vendorCreditAppliedBillModel;
        this.vendorCreditModel = vendorCreditModel;
        this.applyVendorCreditToBills = async (vendorCreditId, applyCreditToBillsDTO) => {
            const vendorCredit = await this.vendorCreditModel()
                .query()
                .findById(vendorCreditId)
                .throwIfNotFound();
            const vendorCreditAppliedModel = this.transformApplyDTOToModel(applyCreditToBillsDTO, vendorCredit);
            const appliedBills = await this.billPaymentValidators.validateBillsExistance(vendorCreditAppliedModel.entries, vendorCredit.vendorId);
            this.validateBillsRemainingAmount(appliedBills, vendorCreditAppliedModel.amount);
            this.vendorCreditDTOTransform.validateCreditRemainingAmount(vendorCredit, vendorCreditAppliedModel.amount);
            return this.uow.withTransaction(async (trx) => {
                const vendorCreditAppliedBills = await this.vendorCreditAppliedBillModel()
                    .query(trx)
                    .insertGraph(vendorCreditAppliedModel.entries);
                await this.documentBalance.incrementBillsCreditedAmount(vendorCreditAppliedBills, trx);
                await this.creditBalance.incrementVendorCreditInvoicedAmount(vendorCredit.id, vendorCreditAppliedModel.amount, trx);
                await this.eventPublisher.emitAsync(events_1.events.vendorCredit.onApplyToInvoicesCreated, {
                    trx,
                    vendorCredit,
                    vendorCreditAppliedBills,
                });
            });
        };
        this.transformApplyDTOToModel = (applyDTO, vendorCredit) => {
            const entries = applyDTO.entries.map((entry) => ({
                billId: entry.billId,
                amount: entry.amount,
                vendorCreditId: vendorCredit.id,
            }));
            const amount = (0, lodash_1.sumBy)(applyDTO.entries, 'amount');
            return {
                amount,
                entries,
            };
        };
        this.validateBillsRemainingAmount = (bills, amount) => {
            const invalidBills = bills.filter((bill) => bill.dueAmount < amount);
            if (invalidBills.length > 0) {
                throw new ServiceError_1.ServiceError(VendorCreditsApplyBills_constants_1.ERRORS.BILLS_HAS_NO_REMAINING_AMOUNT);
            }
        };
    }
};

