let CommandCreditNoteDTOTransform = class CommandCreditNoteDTOTransform {
    constructor(itemsEntriesService, branchDTOTransform, warehouseDTOTransform, brandingTemplatesTransformer, creditNoteAutoIncrement) {
        this.itemsEntriesService = itemsEntriesService;
        this.branchDTOTransform = branchDTOTransform;
        this.warehouseDTOTransform = warehouseDTOTransform;
        this.brandingTemplatesTransformer = brandingTemplatesTransformer;
        this.creditNoteAutoIncrement = creditNoteAutoIncrement;
        this.transformCreateEditDTOToModel = async (creditNoteDTO, customerCurrencyCode, oldCreditNote) => {
            const amount = this.itemsEntriesService.getTotalItemsEntries(creditNoteDTO.entries);
            const entries = R.compose(associate_item_entries_index_1.assocItemEntriesDefaultIndex, R.map((entry) => ({
                ...entry,
                referenceType: 'CreditNote',
            })))(creditNoteDTO.entries);
            const autoNextNumber = this.creditNoteAutoIncrement.getNextCreditNumber();
            const creditNoteNumber = creditNoteDTO.creditNoteNumber ||
                oldCreditNote?.creditNoteNumber ||
                autoNextNumber;
            const initialDTO = {
                ...(0, format_date_fields_1.formatDateFields)((0, lodash_1.omit)(creditNoteDTO, ['open', 'attachments']), ['creditNoteDate']),
                creditNoteNumber,
                amount,
                currencyCode: customerCurrencyCode,
                exchangeRate: creditNoteDTO.exchangeRate || 1,
                entries,
                ...(creditNoteDTO.open &&
                    !oldCreditNote?.openedAt && {
                    openedAt: moment().toMySqlDateTime(),
                }),
                refundedAmount: 0,
                invoicesAmount: 0,
            };
            const asyncDto = (await composeAsync((this.branchDTOTransform.transformDTO), (this.warehouseDTOTransform.transformDTO), this.brandingTemplatesTransformer.assocDefaultBrandingTemplate('CreditNote'))(initialDTO));
            return asyncDto;
        };
        this.validateCreditRemainingAmount = (creditNote, amount) => {
            if (creditNote.creditsRemaining < amount) {
                throw new ServiceError_1.ServiceError(constants_1.ERRORS.CREDIT_NOTE_HAS_NO_REMAINING_AMOUNT);
            }
        };
    }
};
